UPDATE `pages` SET `content` = '{"heading":{"eyebrow":{"en":"Georgia / Our heritage","ka":""},"title":{"en":"Georgian wine.","ka":""},"subtitle":{"en":"The character behind Badagoni. The traditions that connect our wines to their place.","ka":""}},"figure":{"tabLabel":{"en":"Badagoni figure","ka":""},"eyebrow":{"en":"01 / Badagoni figure","ka":""},"title":{"en":"Badagoni Figure","ka":""},"body":{"en":"Discovered in 1958 at an ancient pagan sanctuary in Melaani, Kakheti, this bronze figure dates to approximately the 10th–9th centuries BC. Depicted holding a drinking horn, the figure has been associated by researchers with Badagoni — an ancient Georgian deity connected with wine, fertility, and viticulture. It stands as a remarkable symbol of the deep relationship between wine and Georgian culture.","ka":""},"image":"/images/badagoni-figure-melaani.jpg","imageTitle":{"en":"Bronze figure from Melaani","ka":""},"imageCaption":{"en":"Georgian National Museum","ka":""},"credit":{"label":{"en":"三猎 / Wikimedia Commons","ka":""},"url":"https://commons.wikimedia.org/wiki/File:%E6%A2%85%E6%8B%89%E9%98%BF%E5%B0%BC%E9%9D%92%E9%93%9C%E7%94%B7%E5%AD%90%E5%83%8F.jpg","license":{"en":"CC BY-SA 4.0","ka":""},"licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}},"qvevri":{"tabLabel":{"en":"Qvevri tradition","ka":""},"eyebrow":{"en":"02 / Qvevri tradition","ka":""},"title":{"en":"Qvevri Tradition.","ka":""},"body":{"en":"A qvevri is a clay vessel buried in the ground, used for fermenting and ageing wine. It lies at the heart of a Georgian winemaking tradition passed from one generation to the next.\n\nGrape skins and seeds stay in contact with the wine during and after fermentation, giving it colour, texture, and depth. The vessel, the harvest, and time shape each expression.\n\nAt Alaverdi Monastery, this craft remains part of everyday life. Badagoni supported the restoration of the historic cellar in 2006, helping continue a tradition that lives on in our qvevri wines.","ka":""},"image":"/images/cellar.webp","imageTitle":{"en":"Alaverdi Monastery","ka":""},"imageCaption":{"en":"The qvevri cellar / Kakheti, Georgia","ka":""},"credit":null}}', `updated_at` = CURRENT_TIMESTAMP WHERE `slug` = 'georgian-wine';
